// Random IDs for lessons and entries (docs/DESIGN.md, "The collaborative
// document"): 16 characters of base 62, generated by whoever creates the
// object. 62^16 ≈ 4.8e28, so collisions are not a practical concern.
const ALPHABET = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz'
export const ID_LENGTH = 16

export function randomId(): string {
  let id = ''
  while (id.length < ID_LENGTH) {
    const bytes = crypto.getRandomValues(new Uint8Array(ID_LENGTH * 2))
    for (const byte of bytes) {
      // 248 = 4 × 62: rejecting larger bytes keeps every character equally likely.
      if (byte < 248 && id.length < ID_LENGTH) id += ALPHABET[byte % 62]
    }
  }
  return id
}
